/* 所有任务状态只由 phase 驱动；作答后立即锁定，防止重复计数。 */
(()=>{'use strict';
const C=AttentionCore,PROJECT='6NU4VG',LAB='https://attention-lab-production.up.railway.app',main=document.querySelector('#main');
// demo/quick 旧链接参数不再关闭上传或缩短实验；联调也上传，只标记测试来源。
const TEST=new URLSearchParams(location.search).get('test')==='1';
const PARTIAL='attention-active-v2'+(TEST?'-qa':''),STORE='attention-studio-v1'+(TEST?'-qa':''),labels={feature:'特征搜索',conjunction:'联合搜索',grouped:'颜色分组',bar:'共同基线条形',pie:'无刻度饼图',pie_ticks:'四分刻度饼图'};
let db;try{db=JSON.parse(localStorage.getItem(STORE)||'null');}catch{}db??={participant:(TEST?'TEST-':'P-')+crypto.randomUUID().replaceAll('-','').slice(0,12),sessions:[],consent:false};
let observationData=null,observationLoading=false,observationLoadedAt='',observationError='',observationState={mode:'person',person:'',task:'search',phase:'formal',showTests:false};
let run=null,timer=null,raf=null,epoch=0,screen='home',cloud=null,storageOK=true,flushing=false;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=1)=>v==null||!Number.isFinite(v)?'—':v.toFixed(d);
function save(){try{localStorage.setItem(STORE,JSON.stringify(db));storageOK=true;}catch{storageOK=false;notify('本地存储不可用，请在结束页下载数据备份。');}}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');setTimeout(()=>$('#notice').classList.remove('show'),5000);}
function cancelTimers(){clearTimeout(timer);cancelAnimationFrame(raf);epoch++;}
function setView(v){if(run&&run.phase!=='done'){notify('请先完成或退出当前实验。');return;}screen=v;document.body.classList.remove('during-experiment');if(v==='home')home();if(v==='results')results();if(v==='design')design();window.scrollTo(0,0);}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();setView('home');};
const artwork=`<svg viewBox="0 0 450 280" aria-hidden="true"><g fill="none" stroke="#b8c7ac"><circle cx="225" cy="125" r="105"/><circle cx="225" cy="125" r="70"/><path d="M45 125h360M225 15v220" stroke-dasharray="3 7"/></g><g fill="#758b78" font-family="monospace" font-size="28"><text x="110" y="85">L</text><text x="290" y="65">T</text><text x="320" y="150">L</text><text x="150" y="205">T</text><text x="95" y="160">T</text><text x="267" y="213">L</text></g><circle cx="225" cy="125" r="35" fill="#dce9a6"/><text x="212" y="136" fill="#bd5439" font-size="35" font-family="monospace">T</text></svg>`;
function icon(task){return task==='search'?`<svg viewBox="0 0 330 140" aria-hidden="true"><g font-family="monospace" font-size="27" fill="#25818a"><text x="35" y="40">T</text><text x="105" y="40">T</text><text x="175" y="40">T</text><text x="245" y="40">T</text><text x="35" y="100">T</text><text x="105" y="100">T</text><text x="245" y="100">T</text></g><circle cx="183" cy="90" r="24" fill="#e2eac9"/><text x="175" y="100" font-family="monospace" font-size="27" fill="#bb493b">T</text></svg>`:`<svg viewBox="0 0 330 140" aria-hidden="true"><circle cx="85" cy="70" r="48" fill="#dce5cf"/><path d="M85 70L85 22 A48 48 0 0 1 129 89Z" fill="#d8734a"/><path d="M200 110h100" stroke="#9aaa96"/><path d="M220 110V25" stroke="#c5d5b6" stroke-width="28"/><path d="M275 110V61" stroke="#d8734a" stroke-width="28"/></svg>`;}
function home(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">TWO EXPERIMENTS / ONE QUESTION</div><h1>我们怎样找到目标，<br>又怎样<em>看懂信息？</em></h1><p>从一眼找到的红色 T，到一张图里的比例。用两个小实验，观察注意如何被界面引导。</p><button class="primary" id="begin">开始参与 →</button> <span class="subtle">建议电脑 · 约12–18分钟</span></div><div class="hero-art">${artwork}<small>SEARCH / PERCEPTION / DESIGN</small></div></section><div class="strip"><span><b>02</b> 个经典范式</span><span><b>02</b> 个新增条件</span><span><b>匿名编号</b> · 无姓名、学号</span><span><b>真实收数</b> · 老师后台同步</span></div><div class="section-head"><h2>选择你的观察入口</h2><span>每个实验：说明 → 练习 → 正式 → 结果</span></div><div class="cards">${['search','graph'].map((t,i)=>`<article class="card"><span class="tag ${i?'orange':''}">EXPERIMENT 0${i+1} · ${i?'W7 显示设计':'W6 视觉搜索'}</span><h2>${i?'多少，才是你看到的多少？':'一个红色 T，藏在哪里？'}</h2><p>${i?'比较条形与饼图的比例判断；观察参照刻度能否帮助估计。':'寻找红色 T；比较特征、联合与颜色分组后的搜索表现。'}</p><div class="card-visual">${icon(t)}</div><div class="card-bottom"><span class="subtle">${i?'6次练习 · 60次正式':'12次练习 · 180次正式'}</span><button data-task="${t}">进入实验 ↗</button></div></article>`).join('')}</div><section class="panel row spaced"><div><strong>数据来自参与，不来自示例。</strong><div class="subtle">没有被试时显示空结果；个人记录会先保存在本机。</div></div><button id="observe">查看数据观察 →</button></section>`;$('#begin').onclick=()=>intro(order()[0]);$('#observe').onclick=()=>setView('results');main.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>intro(b.dataset.task));}
function order(){return parseInt(db.participant.slice(-2),16)%2?['graph','search']:['search','graph'];}
function intro(task){screen='intro';main.innerHTML=`<div class="narrow"><div class="eyebrow">BEFORE WE BEGIN</div><h1>${task==='search'?'视觉搜索实验':'图形比例判断实验'}</h1><p>匿名编号 <b>${esc(db.participant)}</b> · 建议顺序：${order().map(x=>x==='search'?'视觉搜索':'比例判断').join(' → ')}</p><div class="panel"><h2>参与说明与知情同意</h2><p>这是工程心理学课程作业，用于比较界面条件下的反应时、正确率与判断误差，不用于个人能力诊断。</p><p>记录内容：随机匿名编号、实验条件、按键或比例估计、反应时、正确性、页面中断标记及试次时间。练习、正式作答、无效试次和中途退出的已有记录都会上传到老师的注意实验室项目 <b>${PROJECT}</b>，作者和教师可下载；项目匿名数据接口也可供知道项目码的人读取。请勿输入姓名、学号或其他身份信息。</p><p>参与自愿，可随时退出。每轮练习或正式阶段结束、或主动退出时上传已有数据；异常关闭会保留本机备份，下次打开补传。已上传数据如需撤回，请向作业作者提供上方匿名编号。建议每人两个实验各做一次；同一浏览器更换被试请在数据页生成新编号。</p><label class="consent"><input type="checkbox" id="consent"><span>我已阅读以上说明，愿意匿名参与并同意上传本次练习、正式作答及中断记录。</span></label></div><div class="instruction">${task==='search'?'<p>目标永远是 <b style="color:#bb493b">红色 T</b>。红色 L 和蓝绿色 T 都不是目标。</p><p>有目标按 <kbd>F</kbd>，没有目标按 <kbd>J</kbd>。也可点屏幕按钮。</p><p>先看注视点，图形出现后尽快准确作答；每次最多5秒。正式阶段不即时告诉对错，每30次休息。</p>':'<p>估计橙色部分占参照整体的百分比：条形条件比较橙色条与绿色参照条；饼图条件比较橙色扇形与整圆。</p><p>输入0–100之间的数，不要用尺量或截图计算。按回车或点击确认。每次最多30秒。</p><p>练习提供真值，正式阶段不反馈答案；每20次可休息。</p>'}</div><p class="subtle">练习也上传并单独标记。切换窗口会暂停，受影响试次会重做。手机可体验，但建议正式数据使用电脑和固定输入方式。</p><div class="row"><button id="back">返回大厅</button><button class="primary" id="practice" disabled>同意并开始练习</button></div></div>`;$('#consent').onchange=e=>$('#practice').disabled=!e.target.checked;$('#practice').onclick=()=>{db.consent=true;save();start(task,true);};$('#back').onclick=()=>setView('home');}
function start(task,practice){cancelTimers();run={id:crypto.randomUUID(),participant:db.participant,isTest:TEST,task,practice,phase:'ready',queue:task==='search'?C.searchTrials(practice):C.graphTrials(practice),trials:[],completed:0,started:new Date().toISOString(),current:null,actualOrder:[...new Set(db.sessions.filter(s=>s.participant===db.participant).map(s=>s.task).concat(task))].join('_')};screen='experiment';run.total=run.queue.length;document.body.classList.add('during-experiment');shell();next();}
function shell(){main.innerHTML=`<div class="stage-wrap"><div class="row spaced"><div><div class="eyebrow">${run.practice?'PRACTICE':'FORMAL SESSION'}</div><h2>${run.task==='search'?'寻找红色 T':'估计橙色比例'}</h2></div><button id="exit">暂停 / 退出</button></div><div class="row spaced"><span id="count"></span><span class="subtle">${run.practice?'练习提供反馈':'正式试次不即时反馈'}</span></div><progress id="progress" max="${run.total}" value="0"></progress><div id="stage" class="stage" aria-label="实验刺激"></div><div id="controls"></div><div id="feedback" class="feedback" aria-live="polite"></div><p class="subtle" style="text-align:center">${run.task==='search'?'只找红色 T · F 有目标 / J 无目标 · 最长5秒':'输入0–100的百分比 · 回车确认 · 最长30秒'}</p></div>`;$('#exit').onclick=()=>pause('你暂停了实验。');}
function next(){if(!run)return;if(run.completed>=run.total){complete();return;}run.current=run.queue.shift();showTrial();}
function showTrial(){cancelTimers();const token=epoch;run.phase='fixation';$('#count').textContent=`${run.practice?'练习':'正式'} ${run.completed+1} / ${run.total}`;$('#progress').value=run.completed;$('#feedback').textContent='';$('#controls').innerHTML='';$('#stage').innerHTML='<span class="fixation">＋</span>';timer=setTimeout(()=>{if(epoch!==token)return;const t=run.current;$('#stage').innerHTML=t.task==='search'?searchSVG(t):graphSVG(t);if(t.task==='search'){$('#controls').innerHTML='<div class="actions"><button id="yes"><kbd>F</kbd> 有红色 T</button><button id="no"><kbd>J</kbd> 没有红色 T</button></div>';$('#yes').onclick=()=>answer(1,'pointer');$('#no').onclick=()=>answer(0,'pointer');}else{$('#controls').innerHTML='<form class="answer" id="estimate"><label for="percent">我的估计</label><input id="percent" type="number" min="0" max="100" step="0.1" inputmode="decimal" required autocomplete="off" aria-label="比例百分比"><span>%</span><button type="submit">确认 →</button></form>';$('#estimate').onsubmit=e=>{e.preventDefault();let raw=$('#percent').value;if(raw==='')return;let v=Number(raw);if(Number.isFinite(v)&&v>=0&&v<=100)answer(v,'estimate');};$('#percent').focus();}raf=requestAnimationFrame(()=>{if(epoch!==token)return;run.onset=performance.now();run.phase='stimulus';timer=setTimeout(()=>answer(-1,'timeout'),t.task==='search'?5000:30000);});},450);}
function searchSVG(t){const items=C.searchItems(t);run.stimulus=C.encodeStimulus(items);return `<svg viewBox="0 0 600 420" role="img" aria-label="搜索阵列">${items.map(i=>`<text x="${85+(i.cell%6)*86}" y="${49+Math.floor(i.cell/6)*65}" text-anchor="middle" dominant-baseline="middle" fill="${i.color==='red'?'#bb493b':'#25818a'}" font-family="Arial,sans-serif" font-size="30" font-weight="600">${i.shape}</text>`).join('')}</svg>`;}
function graphSVG(t){let content='';if(t.mode==='bar'){content=`<path d="M140 340H460" stroke="#899e8c"/><rect x="195" y="90" width="65" height="250" fill="#bdcda7"/><rect x="340" y="${340-t.truth*2.5}" width="65" height="${t.truth*2.5}" fill="#d8734a"/><text x="228" y="370" text-anchor="middle">参照整体</text><text x="373" y="370" text-anchor="middle">目标</text>`;}else{const a=t.truth/100*Math.PI*2,x=300+130*Math.sin(a),y=205-130*Math.cos(a);content=`<circle cx="300" cy="205" r="130" fill="#dce5cf"/><path d="M300 205 L300 75 A130 130 0 ${t.truth>50?1:0} 1 ${x} ${y} Z" fill="#d8734a"/>`;if(t.mode==='pie_ticks'){for(let k=0;k<4;k++){let q=k*Math.PI/2;content+=`<line x1="${300+122*Math.sin(q)}" y1="${205-122*Math.cos(q)}" x2="${300+142*Math.sin(q)}" y2="${205-142*Math.cos(q)}" stroke="#526d56" stroke-width="2"/><text x="${300+161*Math.sin(q)}" y="${210-161*Math.cos(q)}" text-anchor="middle" font-size="14">${k*25}%</text>`;}}}return `<svg viewBox="0 0 600 420" role="img" aria-label="比例估计图形" font-family="Arial,sans-serif" fill="#3d574b">${content}</svg>`;}
function record(value,mode,valid,reason=''){const t=run.current,rt=Math.max(0,Math.round(performance.now()-(run.onset||performance.now()))),timeout=mode==='timeout';return{...t,session:run.id,participant:db.participant,protocol:C.VERSION,practice:run.practice?1:0,is_demo:0,is_test:TEST?1:0,trial:run.trials.length+1,response:value,response_mode:mode,rt,correct:valid&&!timeout&&(t.task==='search'?value===t.present:Math.abs(value-t.truth)<=5)?1:0,valid:valid?1:0,invalid_reason:reason,timeout:timeout?1:0,abs_error:t.task==='graph'&&!timeout&&valid?Math.abs(value-t.truth):-1,log_error:t.task==='graph'&&!timeout&&valid?Math.log2(Math.abs(value-t.truth)+.125):-1,stimulus:run.stimulus||'',started_at:run.started,consent_version:'2026-11-02',experiment_order:run.actualOrder,recommended_order:order().join('_'),viewport_w:innerWidth,viewport_h:innerHeight};}
function answer(value,mode){if(!run||run.phase!=='stimulus')return;run.phase='feedback';cancelTimers();const tooFast=performance.now()-run.onset<150,r=record(value,mode,!tooFast,tooFast?'anticipation':'');run.trials.push(r);if(tooFast)run.queue.push(run.current);else run.completed++;$('#controls').innerHTML='';$('#stage').innerHTML='<span class="fixation">·</span>';$('#feedback').textContent=tooFast?'反应过快，本试次稍后重做。':run.practice?(r.timeout?'未及时作答。':run.task==='search'?(r.correct?'正确':'请留意颜色与形状：目标是红色 T'):`真实比例 ${r.truth}%；你的误差 ${fmt(r.abs_error)} 个百分点`):'已记录';persistPartial();timer=setTimeout(()=>{if(run.completed>=run.total){complete();return;}if(!run.practice&&run.completed>0&&run.completed%(run.task==='search'?30:20)===0&&!tooFast)rest();else next();},run.practice?900:220);}
function persistPartial(){if(!run?.trials.length)return;try{localStorage.setItem(PARTIAL,JSON.stringify({id:run.id,participant:run.participant,task:run.task,practice:run.practice,isTest:run.isTest,trials:run.trials}));}catch{notify('本地备份失败，请结束后立即下载数据。');}}
function archiveRun(complete){const s=C.makeUploadSession(run,complete);if(s&&!db.sessions.some(x=>x.id===s.id)){db.sessions.push(s);save();}try{localStorage.removeItem(PARTIAL);}catch{}return s;}
function recoverRecords(){
 // 老版体验数据按原来源标记为测试，上传后仍不混入研究样本。
 if(!TEST){try{const old=JSON.parse(localStorage.getItem('attention-studio-v1-demo')||'null');for(const r of old?.sessions||[]){if(!db.sessions.some(s=>s.id===r.id)){const s=C.makeUploadSession({...r,isTest:true,practice:!!r.practice},false);if(s)db.sessions.push(s);}}}catch{}}
 try{const old=JSON.parse(sessionStorage.getItem('attention-partial')||'null');if(old?.trials?.length){const s=C.makeUploadSession({...old,id:old.trials[0].session,practice:old.trials[0].practice===1},false);if(s&&!db.sessions.some(x=>x.id===s.id))db.sessions.push(s);sessionStorage.removeItem('attention-partial');}}catch{}
 try{const r=JSON.parse(localStorage.getItem(PARTIAL)||'null');if(r){const s=C.makeUploadSession(r,false);if(s&&!db.sessions.some(x=>x.id===s.id))db.sessions.push(s);save();localStorage.removeItem(PARTIAL);}}catch{}
 save();
}
async function flushQueue(){if(flushing)return;flushing=true;try{for(const s of db.sessions.filter(x=>!['uploaded','uploading'].includes(x.status))){const ok=s.status==='pending'?await submit(s):await retry(s);if(!ok)break;}}finally{flushing=false;}}
window.addEventListener('online',flushQueue);
window.addEventListener('pagehide',()=>{if(run&&run.phase!=='done')persistPartial();});
setInterval(()=>{if(!run||run.phase==='done'||run.phase==='rest'||run.phase==='paused')flushQueue();},60000);
function pause(msg){if(!run||run.phase==='done'||run.phase==='paused')return;if(run.phase==='stimulus'){run.trials.push(record(-1,'interrupted',false,'visibility_or_pause'));persistPartial();}const wasFeedback=run.phase==='feedback'||run.phase==='rest';cancelTimers();run.phase='paused';$('#stage').innerHTML=`<div class="stage-message"><h2>已暂停</h2><p>${esc(msg)}</p><p class="subtle">受影响的呈现不会进入有效数据。</p><button id="resume" class="primary">继续</button> <button id="leave">退出并上传已有记录</button></div>`;$('#controls').innerHTML='';$('#resume').onclick=()=>{if(wasFeedback)next();else showTrial();};$('#leave').onclick=()=>{cancelTimers();archiveRun(false);run=null;setView('results');flushQueue();};}
function rest(){run.phase='rest';$('#stage').innerHTML=`<div class="stage-message"><h2>休息一下眼睛</h2><p>已完成 ${run.completed} / ${run.total} 次</p><button id="continue" class="primary">准备好了，继续 →</button></div>`;$('#continue').onclick=next;}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&run&&['stimulus','fixation','feedback'].includes(run.phase))pause('页面切到后台，已暂停计时。');});window.addEventListener('blur',()=>{if(run&&['stimulus','fixation'].includes(run.phase))pause('窗口失去焦点，已暂停计时。');});window.addEventListener('resize',()=>{if(run&&['stimulus','fixation'].includes(run.phase))pause('显示区域改变，重新呈现后继续。');});
document.addEventListener('keydown',e=>{if(e.repeat||!run||run.task!=='search'||run.phase!=='stimulus')return;if(e.code==='KeyF'||e.code==='KeyJ'){e.preventDefault();answer(e.code==='KeyF'?1:0,'keyboard');}});
function complete(){cancelTimers();run.phase='done';archiveRun(true);document.body.classList.remove('during-experiment');if(run.practice){const task=run.task,valid=run.trials.filter(t=>t.valid);const acc=C.mean(valid.map(t=>t.correct));screen='practice-result';main.innerHTML=`<div class="narrow panel"><div class="eyebrow">PRACTICE COMPLETE</div><h1>练习完成</h1><p>${task==='search'?`正确率 ${fmt(acc*100,0)}%。正式阶段只找红色 T。`:'正式阶段仍估计橙色占参照整体的比例，但不会即时给出真值。'}</p>${task==='search'&&acc<.75?'<p class="warning">当前正确率低于75%，请再练一轮确认规则。</p>':''}<div class="row"><button id="again">再练一轮</button><button class="primary" id="formal" ${task==='search'&&acc<.75?'disabled':''}>开始正式实验</button></div><p class="subtle">本轮练习记录已进入上传队列，单独标记为练习。可在“数据观察”查看上传状态。</p></div>`;$('#again').onclick=()=>start(task,true);$('#formal').onclick=()=>start(task,false);flushQueue();return;}run=null;results();flushQueue();}
async function submit(s){if(s.status==='uploaded')return true;if(s.status==='uploading'||!s.trials.length)return false;s.status='uploading';s.message='正在上传';save();if(screen==='results')results();const controller=new AbortController(),deadline=setTimeout(()=>controller.abort(),15000);try{const payload=JSON.stringify({project:PROJECT,participant:s.participant,experiment:s.experiment,condition:s.trials[0].experiment_order,trials:s.trials,meta:{protocol:C.VERSION,session:s.id,practice:!!s.practice,complete:s.complete!==false,is_test:!!s.isTest}});if(new Blob([payload]).size>250000)throw Error('数据超过接口单次大小限制，请下载备份联系作者');const res=await fetch(LAB+'/api/hw2/submit',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:payload});const data=await res.json();if(!res.ok||!data.ok)throw Error(data.msg||'接口未确认成功');s.status='uploaded';s.message=`已上传 · 记录 ${data.record_id??'已确认'}`;}catch(e){s.status='uncertain';s.message='未确认上传成功：'+(e.name==='AbortError'?'网络超时':e.message)+'。重试前将按session检查，避免重复。';}finally{clearTimeout(deadline);save();if(screen==='results')results();}return s.status==='uploaded';}
async function retry(s){if(s.status==='uploading'||s.checking)return false;s.checking=true;try{const res=await fetch(`${LAB}/api/hw2/data?project=${PROJECT}&experiment=${s.experiment}`,{signal:AbortSignal.timeout(15000)});const data=await res.json();if(!res.ok||!data.ok||!Array.isArray(data.records))throw Error('无法读取后台确认状态');if(data.records.some(r=>r.trials?.some(t=>t.session===s.id))){s.status='uploaded';s.message='已在后台找到同一session，未重复上传';save();if(screen==='results')results();return true;}s.status='pending';return await submit(s);}catch(e){s.status='uncertain';s.message='暂无法核对后台，将在联网后重试；可先下载备份。';save();if(screen==='results')results();return false;}finally{s.checking=false;}}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function localRecords(task){return db.sessions.filter(s=>s.task===task).map(s=>({participant:s.participant,trials:s.trials}));}
function rowsTable(rows,task){if(!rows.length)return '<p class="empty">暂无符合当前范围的有效数据。</p>';return `<div class="scroll"><table><thead><tr><th>条件</th>${task==='search'?'<th>数量 / 目标</th>':''}<th>有效试次</th><th>超时率</th><th>${task==='search'?'正确率':'平均绝对误差'}</th><th>${task==='search'?'正确反应时':'平均反应时'}</th><th>${task==='search'?'计时样本':'平均 log₂ 误差'}</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(labels[r.mode])}</td>${task==='search'?`<td>${r.size} / ${r.present?'有':'无'}</td>`:''}<td>${r.n}</td><td>${fmt(r.timeoutRate*100)}%</td><td>${task==='search'?fmt(r.accuracy*100)+'%':fmt(r.mae)+' pp'}</td><td>${fmt(r.rt,0)} ms</td><td>${task==='search'?r.rtN:fmt(r.logError,3)}</td></tr>`).join('')}</tbody></table></div>`;}
function results(){screen='results';const current=db.sessions.filter(s=>s.participant===db.participant),ss=current.filter(s=>s.task==='search'&&!s.practice&&s.complete!==false&&!s.isTest).at(-1),gs=current.filter(s=>s.task==='graph'&&!s.practice&&s.complete!==false&&!s.isTest).at(-1);main.innerHTML=`<div class="eyebrow">OBSERVE THE EVIDENCE</div><h1>让数据回答，而不是替数据回答。</h1><p class="subtle">当前匿名编号 ${esc(db.participant)}。可查看单个或所有被试的图表，后台数据会自动读取。</p><div id="observation"></div><details class="local-backups"><summary>本机上传状态与数据备份</summary><div class="stat-grid"><div class="stat"><strong>${current.length}</strong><span>当前编号保存的练习与实验记录</span></div><div class="stat"><strong>${current.filter(s=>s.status==='uploaded').length}</strong><span>已获后台成功确认</span></div><div class="stat"><strong>${PROJECT}</strong><span>老师后台项目码</span></div></div><div class="panel"><div class="row spaced"><h2>数据上传与备份</h2><button id="new-person">换一位被试</button></div>${!storageOK?'<p class="warning">本地存储不可用，请立即下载备份。</p>':''}${db.sessions.length?db.sessions.map(s=>`<div class="panel"><div class="row spaced"><strong>${s.task==='search'?'视觉搜索':'比例判断'} · ${s.practice?'练习':'正式'}${s.complete===false?' · 中断记录':''}${s.isTest?' · 测试':''} · ${esc(s.participant)}</strong><span class="${s.status==='uploaded'?'success':'error'}">${esc(s.message||'尚未上传')}</span></div><div class="row"><button data-csv="${s.id}">下载CSV</button><button data-json="${s.id}">下载JSON</button>${s.status!=='uploaded'?`<button data-retry="${s.id}" ${s.status==='uploading'?'disabled':''}>核对并重试上传</button>`:''}</div></div>`).join(''):'<p>尚无完成记录。</p>'}<div id="partial"></div></div></details><div class="row"><button data-next="${ss?'graph':'search'}" class="primary">${ss?'进入比例判断':'进入视觉搜索'} →</button><button id="go-design">分析方法与论文出处</button></div>`;$('#new-person').onclick=()=>{db.participant=(TEST?'TEST-':'P-')+crypto.randomUUID().replaceAll('-','').slice(0,12);db.consent=false;save();setView('home');};main.querySelectorAll('[data-csv]').forEach(b=>b.onclick=()=>{const s=db.sessions.find(s=>s.id===b.dataset.csv);download(s.experiment+'-'+s.participant+'.csv',C.csv(s.trials),'text/csv;charset=utf-8');});main.querySelectorAll('[data-json]').forEach(b=>b.onclick=()=>{const s=db.sessions.find(s=>s.id===b.dataset.json);download(s.experiment+'-'+s.participant+'.json',JSON.stringify(s,null,2),'application/json');});main.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>retry(db.sessions.find(s=>s.id===b.dataset.retry)));$('[data-next]').onclick=e=>intro(e.target.dataset.next);$('#go-design').onclick=()=>setView('design');renderObservation();if(observationData===null&&!observationLoading&&!observationError)loadAll();}
function slopesHTML(slopes){return `<h3>搜索斜率（ms / 项）</h3><div class="scroll"><table><thead><tr><th>条件</th><th>目标存在</th><th>目标不存在</th></tr></thead><tbody>${['feature','conjunction','grouped'].map(m=>`<tr><td>${labels[m]}</td><td>${fmt(slopes[m+'_1'],2)}</td><td>${fmt(slopes[m+'_0'],2)}</td></tr>`).join('')}</tbody></table></div><p class="subtle">基于正确且非超时反应，12/24/36项均有可用反应时才作线性回归。数值越大，项目增多带来的耗时越明显。</p>`;}
function observationEffects(records,task){
 if(observationState.phase!=='formal'||!records.length)return '';
 const people=records.map(r=>({rows:C.summarize(r.trials,task),slopes:task==='search'?C.searchSlopes(r.trials):{}}));
 const pairs=people.map(p=>{if(task==='search')return [p.slopes.conjunction_1,p.slopes.feature_1,p.slopes.grouped_1];return ['pie','bar','pie_ticks'].map(m=>p.rows.find(r=>r.mode===m)?.mae);}).filter(a=>a.every(v=>typeof v==='number'&&Number.isFinite(v)));
 const meanDifference=(index)=>C.mean(pairs.map(a=>a[0]-a[index]));
 let slopes='';if(task==='search'){const averaged={};for(const mode of ['feature','conjunction','grouped'])for(const present of [0,1]){const key=mode+'_'+present;averaged[key]=C.mean(people.map(p=>p.slopes[key]).filter(v=>v!==null));}slopes=slopesHTML(averaged);}
 return `${slopes}<h3>配对效应 · ${pairs.length}名可计算</h3><div class="scroll"><table><tr><th>经典对比</th><td>${task==='search'?'联合−特征（目标存在）':'饼图误差−条形误差'}</td><td>${fmt(meanDifference(1),2)} ${task==='search'?'ms/项':'pp'}</td></tr><tr><th>改进收益</th><td>${task==='search'?'联合−颜色分组（目标存在）':'无刻度误差−有刻度误差'}</td><td>${fmt(meanDifference(2),2)} ${task==='search'?'ms/项':'pp'}</td></tr></table></div><p class="subtle">配对差值先逐人计算再平均；描述性结果不等于统计显著。</p>`;
}
function renderObservation(){
 const host=$('#observation');if(!host)return;
 const records=C.observationRecords(observationData||[],db.sessions),available=C.latestObservations(records,observationState);
 if(!available.some(r=>r.participant===observationState.person))observationState.person=available.find(r=>r.rawParticipant===db.participant)?.participant||available[0]?.participant||'';
 const chosen=observationState.mode==='person'?available.filter(r=>r.participant===observationState.person):available;
 const task=observationState.task,summary=C.observationSummary(chosen,task),isAll=observationState.mode==='all';
 const phaseName={formal:'正式',practice:'练习',partial:'中断'}[observationState.phase];
 const modes=task==='search'?['feature','conjunction','grouped']:['bar','pie','pie_ticks'];
 const metricItems=(metric,mult=1)=>modes.map(mode=>{const m=C.observationModeMetric(summary.people,mode,metric);return{name:labels[mode],value:m.value===null?null:m.value*mult,n:m.n};});
 let plots='';
 if(chosen.length&&summary.rows.length){
  if(task==='search'){
   const sizes=[...new Set(summary.rows.map(r=>r.size))].sort((a,b)=>a-b),rtLimit=Math.max(100,Math.ceil(Math.max(0,...summary.rows.map(r=>r.rt||0))/100)*100);
   plots=`<div class="plot-grid">${[1,0].map(present=>AttentionCharts.line(`正确反应时 · 目标${present?'存在':'不存在'}`,sizes,modes.map(mode=>({name:labels[mode],values:sizes.map(size=>summary.rows.find(r=>r.mode===mode&&r.present===present&&r.size===size)?.rt??null)})),'ms',rtLimit)).join('')}${AttentionCharts.bars('正确率 · 全部项目数',metricItems('accuracy',100),'%',100)}${AttentionCharts.bars('超时率 · 全部项目数',metricItems('timeoutRate',100),'%',100)}</div>`;
  }else plots=`<div class="plot-grid">${AttentionCharts.bars('平均绝对误差 · 越低越准确',metricItems('mae'),'pp')}${AttentionCharts.bars('平均反应时',metricItems('rt'),'ms')}${AttentionCharts.bars('误差≤5个百分点的比例',metricItems('accuracy',100),'%',100)}${AttentionCharts.bars('超时率',metricItems('timeoutRate',100),'%',100)}</div>`;
 }else plots='<div class="empty chart-empty"><strong>这个范围还没有可绘制的数据</strong><p>可切换实验、阶段或被试，或点击“更新后台数据”。缺失数据不会画成0。</p></div>';
 host.innerHTML=`<section class="observation-panel"><div class="row spaced"><div><div class="eyebrow">RESULTS EXPLORER</div><h2>看看结果长什么样</h2></div><button id="load-all" ${observationLoading?'disabled':''}>${observationLoading?'正在读取…':'更新后台数据'}</button></div><div class="observation-toolbar"><div class="segmented" role="group" aria-label="查看范围"><button data-scope="person" aria-pressed="${!isAll}">单个被试</button><button data-scope="all" aria-pressed="${isAll}">所有被试</button></div><label>被试编号<select id="observation-person" ${isAll||!available.length?'disabled':''}>${available.length?available.map(r=>`<option value="${esc(r.participant)}" ${r.participant===observationState.person?'selected':''}>${esc(r.participant)}${r.isTest?'（测试）':''}${r.source==='本机'?'（本机）':''}</option>`).join(''):'<option value="">暂无被试</option>'}</select></label><label>数据阶段<select id="observation-phase"><option value="formal" ${observationState.phase==='formal'?'selected':''}>正式实验</option><option value="practice" ${observationState.phase==='practice'?'selected':''}>练习</option><option value="partial" ${observationState.phase==='partial'?'selected':''}>中断记录</option></select></label></div><div class="row spaced"><div class="experiment-tabs" role="group" aria-label="选择实验"><button data-plot-task="search" aria-pressed="${task==='search'}">01 视觉搜索</button><button data-plot-task="graph" aria-pressed="${task==='graph'}">02 比例判断</button></div><label class="test-toggle"><input type="checkbox" id="observation-tests" ${observationState.showTests?'checked':''}>包含测试记录</label></div><p class="subtle" role="status">${observationError?esc(observationError):observationLoading?'正在读取后台；已有本机记录仍可查看。':observationLoadedAt?'后台更新于 '+esc(observationLoadedAt)+'；已与本机记录去重。':'当前显示本机记录。'}</p><div class="observation-summary"><div><strong>${isAll?'所有被试':esc(observationState.person||'尚无被试')}</strong><span>${phaseName} · ${task==='search'?'视觉搜索':'比例判断'}</span></div><div><strong>${chosen.length}</strong><span>被试 / 最近一次记录</span></div><div><strong>${summary.totalTrials-summary.invalid} / ${summary.totalTrials}</strong><span>有效 / 全部试次</span></div><div><strong>${summary.invalid} / ${summary.timeouts}</strong><span>无效试次 / 超时</span></div></div>${isAll&&chosen.length===1?'<p class="info-note">目前这个范围只有1名被试，全体均值与该被试的结果相同。</p>':''}<p class="subtle">${isAll?'全体图表先计算每位被试的条件均值，再等权平均。':'展示所选被试在当前阶段最近一次记录。'}练习与正式分开；无效试次保留在总数中，不进入指标。反应时排除超时，搜索反应时还排除错误反应。pp＝百分点。</p>${plots}<details class="chart-table"><summary>查看图表对应的条件数值与试次数</summary>${rowsTable(summary.rows,task)}${observationEffects(chosen,task)}</details></section>`;
 $('#load-all').onclick=loadAll;
 host.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{observationState.mode=b.dataset.scope;renderObservation();});
 host.querySelectorAll('[data-plot-task]').forEach(b=>b.onclick=()=>{observationState.task=b.dataset.plotTask;renderObservation();});
 $('#observation-person').onchange=e=>{observationState.person=e.target.value;renderObservation();};
 $('#observation-phase').onchange=e=>{observationState.phase=e.target.value;renderObservation();};
 $('#observation-tests').onchange=e=>{observationState.showTests=e.target.checked;renderObservation();};
}
async function loadAll(){
 if(observationLoading)return;observationLoading=true;observationError='';renderObservation();
 try{const res=await fetch(`${LAB}/api/hw2/data?project=${PROJECT}`,{signal:AbortSignal.timeout(15000)}),r=await res.json();if(!res.ok||!r.ok||!Array.isArray(r.records))throw Error(r.msg||'数据格式异常');observationData=r.records;observationLoadedAt=new Date().toLocaleTimeString('zh-CN',{hour12:false});}
 catch(e){observationError='后台读取失败，保留已有数据：'+e.message;}
 finally{observationLoading=false;if(screen==='results')renderObservation();}
}

function design(){main.innerHTML=`<div class="narrow"><div class="eyebrow">REPLICATION + A TESTABLE CHANGE</div><h1>先写预测，再看结果。</h1><p>协议版本 ${C.VERSION}。以下预测是待你审阅确认的研究方案草案；正式招募前应确认并在Git提交保存。</p><div class="panel"><h2>01 视觉搜索</h2><p>参考 Treisman &amp; Gelade（1980）的特征整合理论，复现特征与联合搜索的经典差异。这里是浏览器改编，并非逐参数复制原研究。</p><p><b>设计：</b>3种搜索方式 × 3种项目数（12/24/36）× 2种目标状态（有/无）× 每格10次＝180正式试次，随机混排。另12次练习。</p><p><b>新增条件：</b>联合搜索中按颜色分区。红色在左/右平衡；目标仍是红色T，红色L、蓝绿色T仍为干扰。</p><p><b>收数前预测草案：</b>联合搜索的正确RT斜率大于特征搜索；颜色分组降低联合搜索斜率，尤其大阵列可能受益。分组同时改变空间分布，这是解释时需要讨论的设计限制。</p><p><b>主要指标：</b>正确反应时的搜索斜率（分别分析目标存在/缺失）、正确率及超时率。不能只看更快而忽略错误增加。</p><a href="https://doi.org/10.1016/0010-0285(80)90005-5" target="_blank" rel="noopener">Treisman &amp; Gelade, Cognitive Psychology, 12, 97–136 ↗</a></div><div class="panel"><h2>02 图形比例判断</h2><p>参考 Cleveland &amp; McGill（1984）对图形编码知觉精度的实验，比较共同基线长度与扇形角度判断。此处使用整体比例任务，属于范式改编，不将所得误差当作原文的精确复现。</p><p><b>设计：</b>条形、无刻度饼图、有四分刻度饼图，各20次＝60正式试次；同一组真实比例用于全部条件，随机混排。另6次练习。</p><p><b>新增条件：</b>饼图增加0/25/50/75%参照刻度，利用外部参照减少估计负担。</p><p><b>收数前预测草案：</b>条形的平均绝对误差小于无刻度饼图；增加刻度降低饼图误差。刻度是否付出更长判断时间，须同时报告RT。</p><p><b>指标：</b>绝对误差（百分点），以及 log₂(|估计−真值|＋0.125)；正确字段仅按“误差≤5个百分点”作为描述指标，不代表原论文判分方式。</p><a href="https://doi.org/10.1080/01621459.1984.10478080" target="_blank" rel="noopener">Cleveland &amp; McGill, JASA, 79, 531–554 ↗</a></div><details open><summary>共同的数据处理规则</summary><p>知情同意后开始；练习、正式与中断记录均上传并区分标记；正式条件平衡。使用performance.now()计时，刺激写入后在requestAnimationFrame回调启用作答。网页无法保证显示器物理呈现的毫秒精度。</p><p>反应短于150ms、失焦和窗口改变的试次标记无效并补做；超时记错误，保留在准确率分母，排除RT与比例误差。搜索RT只分析正确且有效试次。不能按结果方向任意删样本。</p><p>全体分析按匿名参与者先计算配对效应，再汇总均值；小样本先报告描述性结果。各条件试次数、错误率、排除数应随报告公开。</p></details><details><summary>交付与真实收数</summary><p>需要至少5名其他参与者分别完成两个实验，不能用本机测试或模拟数据凑人数。代码和预测需在收数前提交到Git；收数后补结果、与论文对照及局限。AI协助的代码和建议应如实写进README。</p><p>下载密钥不放在网页或仓库。只嵌入公开项目码${PROJECT}；每轮练习、正式阶段结束或主动退出时上传已有记录；网络失败保存本机并补传。异常关闭后，下次打开补传已有记录。</p></details><div class="row" style="margin-top:25px"><button class="primary" id="return-home">返回实验大厅</button><a href="PREDICTIONS.md" download>下载预测草案</a></div></div>`;$('#return-home').onclick=()=>setView('home');}

db.sessions.forEach(s=>{delete s.checking;if(s.status==='uploading'){s.status='uncertain';s.message='上次页面关闭，上传状态待核对';}});recoverRecords();save();if(location.hash==='#results')setView('results');else home();flushQueue();
})();
